// ============================================================
// EXAM PAGE — Core exam interface with AI proctoring
// Features: Timer, Question Navigation, Auto-submit,
//           Face detection, Tab-switch detection,
//           Fullscreen enforcement, Anti-copy/paste
// ============================================================
import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import Webcam from '../../components/common/SafeWebcam';
import { examAPI, sessionAPI } from '../../services/api';
import { useAuth } from '../../context/AuthContext';
import toast from 'react-hot-toast';

// ─── Security hooks ───────────────────────────────────────
function useExamSecurity(sessionId, onViolation) {
  useEffect(() => {
    if (!sessionId) return;

    // 1. Prevent copy/paste/cut
    const preventCopy = (e) => { e.preventDefault(); onViolation('copy_paste_attempt', 'Copy/paste attempted'); };
    document.addEventListener('copy', preventCopy);
    document.addEventListener('paste', preventCopy);
    document.addEventListener('cut', preventCopy);

    // 2. Disable right-click
    const preventContext = (e) => e.preventDefault();
    document.addEventListener('contextmenu', preventContext);

    // 3. Disable keyboard shortcuts
    const preventShortcuts = (e) => {
      const blockedKeys = ['F12', 'F5', 'Tab'];
      const blockedCombos = (e.ctrlKey || e.metaKey) && ['c','v','x','a','u','p','s','f','r'].includes(e.key.toLowerCase());
      if (blockedKeys.includes(e.key) || blockedCombos) {
        e.preventDefault();
        onViolation('keyboard_shortcut', `Blocked key: ${e.ctrlKey ? 'Ctrl+' : ''}${e.key}`);
      }
    };
    document.addEventListener('keydown', preventShortcuts);

    // 4. Tab switch / visibility detection
    const handleVisibility = () => {
      if (document.hidden) {
        onViolation('tab_switch', 'Tab switched or window minimized');
      }
    };
    document.addEventListener('visibilitychange', handleVisibility);

    // 5. Window blur (switched away)
    const handleBlur = () => onViolation('tab_switch', 'Window lost focus');
    window.addEventListener('blur', handleBlur);

    return () => {
      document.removeEventListener('copy', preventCopy);
      document.removeEventListener('paste', preventCopy);
      document.removeEventListener('cut', preventCopy);
      document.removeEventListener('contextmenu', preventContext);
      document.removeEventListener('keydown', preventShortcuts);
      document.removeEventListener('visibilitychange', handleVisibility);
      window.removeEventListener('blur', handleBlur);
    };
  }, [sessionId, onViolation]);
}

// ─── Fullscreen hook ──────────────────────────────────────
function useFullscreen(onViolation) {
  const active = useRef(true);

  const enterFullscreen = useCallback(() => {
    if (!active.current) return;
    try {
      const el = document.documentElement;
      if (el.requestFullscreen) el.requestFullscreen().catch(() => {});
      else if (el.webkitRequestFullscreen) el.webkitRequestFullscreen();
    } catch {}
  }, []);

  useEffect(() => {
    active.current = true;
    enterFullscreen();

    const handleFullscreenChange = () => {
      if (!active.current) return;
      if (!document.fullscreenElement) {
        onViolation('fullscreen_exit', 'Exited fullscreen mode');
        setTimeout(() => { if (active.current) enterFullscreen(); }, 1000);
      }
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => {
      active.current = false;
      document.removeEventListener('fullscreenchange', handleFullscreenChange);
      // Exit fullscreen on cleanup (page navigation)
      try { if (document.fullscreenElement) document.exitFullscreen(); } catch {}
    };
  }, [enterFullscreen, onViolation]);

  return { enterFullscreen };
}

// ─── Timer component ──────────────────────────────────────
function ExamTimer({ durationSeconds, onTimeUp }) {
  const [remaining, setRemaining] = useState(durationSeconds);

  useEffect(() => {
    if (remaining <= 0) { onTimeUp(); return; }
    const interval = setInterval(() => setRemaining(r => r - 1), 1000);
    return () => clearInterval(interval);
  }, [remaining, onTimeUp]);

  const hours = Math.floor(remaining / 3600);
  const mins = Math.floor((remaining % 3600) / 60);
  const secs = remaining % 60;
  const pad = (n) => String(n).padStart(2, '0');

  const isWarning = remaining < 300; // < 5 minutes
  const isCritical = remaining < 60; // < 1 minute

  return (
    <div className={`flex items-center gap-2 px-4 py-2 rounded-lg font-mono text-lg font-bold ${
      isCritical ? 'bg-red-600 text-white animate-pulse' :
      isWarning ? 'bg-yellow-100 text-yellow-800' :
      'bg-blue-100 text-blue-800'
    }`}>
      ⏱ {hours > 0 ? `${pad(hours)}:` : ''}{pad(mins)}:{pad(secs)}
    </div>
  );
}

// ─── Main ExamPage ────────────────────────────────────────
export default function ExamPage() {
  const { examId } = useParams();
  const { user } = useAuth();
  const navigate = useNavigate();

  // State
  const [exam, setExam] = useState(null);
  const [session, setSession] = useState(null);
  const [answers, setAnswers] = useState({}); // { questionId: 'A'|'B'|'C'|'D' }
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [phase, setPhase] = useState('verify'); // 'verify' | 'exam' | 'done'
  const [faceVerified, setFaceVerified] = useState(false);
  const [violationCount, setViolationCount] = useState(0);
  const [webcamError, setWebcamError] = useState(false);

  const webcamRef = useRef(null);
  const violationTimestamps = useRef([]); // rate-limit logging

  // Log violation to backend
  const logViolation = useCallback(async (type, description, severity = 'medium') => {
    if (!session) return;

    // Rate-limit: max 1 same violation per 3 seconds
    const now = Date.now();
    const key = `${type}`;
    const last = violationTimestamps.current[key] || 0;
    if (now - last < 3000) return;
    violationTimestamps.current[key] = now;

    setViolationCount(c => c + 1);

    try {
      await sessionAPI.logViolation(session.id, { violation_type: type, severity, description });
    } catch {}

    // Show non-intrusive warning
    if (type === 'tab_switch') toast.error('⚠️ Tab switch detected!', { duration: 2000 });
    if (type === 'fullscreen_exit') toast.error('⚠️ Please stay in fullscreen!', { duration: 2000 });
    if (type === 'copy_paste_attempt') toast.error('⚠️ Copy/paste not allowed!', { duration: 2000 });

    // Auto-terminate after 10 high-severity violations
    if (violationCount >= 10) {
      toast.error('Too many violations. Exam terminated.');
      handleSubmit(true);
    }
  }, [session, violationCount]);

  useExamSecurity(session?.id, logViolation);
  useFullscreen(logViolation);

  // Load exam data
  useEffect(() => {
    examAPI.getById(examId).then(data => {
      setExam(data.exam);
    }).catch(() => toast.error('Failed to load exam'))
      .finally(() => setLoading(false));
  }, [examId]);

  // Start session
  const startSession = async () => {
    try {
      const data = await sessionAPI.start({ exam_id: examId });
      setSession(data.session);

      // Load saved answers if resuming
      if (data.resumed) {
        const savedAnswers = await sessionAPI.getAnswers(data.session.id);
        const answerMap = {};
        savedAnswers.answers.forEach(a => { answerMap[a.question_id] = a.selected_option; });
        setAnswers(answerMap);
        toast.success('Resuming your exam...');
      }

      setPhase('exam');
    } catch (err) {
      toast.error('Failed to start exam session');
    }
  };

  // Save answer
  const selectAnswer = async (questionId, option) => {
    setAnswers(prev => ({ ...prev, [questionId]: option }));
    if (session) {
      try {
        await sessionAPI.saveAnswer(session.id, { question_id: questionId, selected_option: option });
      } catch {}
    }
  };

  // Submit exam
  const handleSubmit = async (autoSubmit = false) => {
    if (submitting) return;
    if (!autoSubmit && !window.confirm('Are you sure you want to submit the exam?')) return;

    setSubmitting(true);
    try {
      const result = await sessionAPI.submit(session.id, { auto_submit: autoSubmit });
      setPhase('done');

      // Exit fullscreen
      if (document.fullscreenElement) document.exitFullscreen();

      navigate(`/exam/result/${session.id}`, { state: { result: result.result, exam } });
    } catch {
      toast.error('Submission failed. Please try again.');
      setSubmitting(false);
    }
  };

  // ─── PHASE: Face Verification ──────────────────────────
  if (phase === 'verify') {
    return (
      <div className="fixed inset-0 bg-gray-900 flex items-center justify-center z-50">
        <div className="bg-white rounded-2xl p-8 max-w-md w-full mx-4 text-center">
          <h2 className="text-2xl font-bold mb-2">Identity Verification</h2>
          <p className="text-gray-500 mb-6">Please look at the camera to verify your identity before starting the exam.</p>

          {!webcamError ? (
            <div className="relative inline-block">
              <Webcam
                ref={webcamRef}
                audio={false}
                screenshotFormat="image/jpeg"
                className="rounded-xl w-64 h-48 object-cover border-4 border-blue-400"
                onUserMediaError={() => setWebcamError(true)}
              />
              <div className="absolute inset-0 border-4 border-blue-400 rounded-xl animate-pulse pointer-events-none"/>
            </div>
          ) : (
            <div className="bg-red-50 p-4 rounded-xl mb-4">
              <p className="text-red-600 text-sm">Camera not available. Proctoring features may be limited.</p>
            </div>
          )}

          <div className="mt-6 space-y-3">
            <div className="flex items-center gap-2 text-sm text-gray-600 bg-yellow-50 p-3 rounded-lg">
              <span>⚠️</span>
              <span>This exam uses AI proctoring. Your webcam will be monitored throughout.</span>
            </div>
            <button
              onClick={async () => {
                if (!webcamError) setFaceVerified(true);
                await startSession();
              }}
              disabled={loading}
              className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 rounded-xl transition"
            >
              {loading ? 'Loading Exam...' : 'Verify & Start Exam'}
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (loading || !exam) {
    return <div className="fixed inset-0 bg-gray-900 flex items-center justify-center">
      <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-white"/>
    </div>;
  }

  const questions = exam.questions || [];
  const currentQuestion = questions[currentIndex];
  const answeredCount = Object.keys(answers).length;

  // ─── PHASE: Exam Interface ─────────────────────────────
  return (
    <div className="fixed inset-0 bg-gray-100 flex flex-col" style={{ userSelect: 'none' }}>

      {/* Top Bar */}
      <header className="bg-white shadow-sm px-6 py-3 flex items-center justify-between z-10">
        <div>
          <h1 className="font-bold text-gray-800 text-lg">{exam.title}</h1>
          <p className="text-sm text-gray-500">{exam.subject} · {questions.length} Questions · {exam.total_marks} Marks</p>
        </div>

        <div className="flex items-center gap-4">
          {/* Webcam preview */}
          {!webcamError && (
            <div className="relative">
              <Webcam
                ref={webcamRef}
                audio={false}
                className="w-20 h-16 rounded-lg object-cover border-2 border-green-400"
                screenshotFormat="image/jpeg"
                onUserMediaError={() => setWebcamError(true)}
              />
              <div className="absolute -top-1 -right-1 w-3 h-3 bg-green-500 rounded-full animate-pulse"/>
            </div>
          )}

          {/* Violation counter */}
          {violationCount > 0 && (
            <div className="flex items-center gap-1 bg-red-100 text-red-700 px-3 py-1 rounded-full text-sm font-medium">
              ⚠️ {violationCount} violations
            </div>
          )}

          {/* Timer */}
          {session && (
            <ExamTimer
              durationSeconds={exam.duration_minutes * 60}
              onTimeUp={() => handleSubmit(true)}
            />
          )}

          {/* Submit button */}
          <button
            onClick={() => handleSubmit(false)}
            disabled={submitting}
            className="bg-red-600 hover:bg-red-700 disabled:bg-red-400 text-white px-5 py-2 rounded-lg font-semibold transition"
          >
            {submitting ? 'Submitting...' : 'Submit Exam'}
          </button>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden">
        {/* Question Navigator (left sidebar) */}
        <aside className="w-64 bg-white shadow-sm overflow-y-auto p-4">
          <div className="mb-3">
            <p className="text-sm font-semibold text-gray-600">Questions</p>
            <p className="text-xs text-gray-400">{answeredCount}/{questions.length} answered</p>
            <div className="w-full bg-gray-200 rounded-full h-1.5 mt-2">
              <div className="bg-blue-600 h-1.5 rounded-full transition-all" style={{ width: `${(answeredCount / questions.length) * 100}%` }}/>
            </div>
          </div>

          <div className="grid grid-cols-5 gap-1.5">
            {questions.map((q, idx) => (
              <button
                key={q.id}
                onClick={() => setCurrentIndex(idx)}
                className={`w-full aspect-square rounded-lg text-xs font-bold transition ${
                  idx === currentIndex ? 'bg-blue-600 text-white ring-2 ring-blue-400' :
                  answers[q.id] ? 'bg-green-500 text-white' :
                  'bg-gray-100 text-gray-600 hover:bg-gray-200'
                }`}
              >
                {idx + 1}
              </button>
            ))}
          </div>

          {/* Legend */}
          <div className="mt-4 space-y-1 text-xs text-gray-500">
            <div className="flex items-center gap-2"><div className="w-4 h-4 bg-green-500 rounded"/><span>Answered</span></div>
            <div className="flex items-center gap-2"><div className="w-4 h-4 bg-blue-600 rounded"/><span>Current</span></div>
            <div className="flex items-center gap-2"><div className="w-4 h-4 bg-gray-100 border rounded"/><span>Not answered</span></div>
          </div>
        </aside>

        {/* Question Area */}
        <main className="flex-1 overflow-y-auto p-6">
          {currentQuestion && (
            <div className="max-w-3xl mx-auto">
              <div className="bg-white rounded-2xl shadow-sm p-8">
                {/* Question Header */}
                <div className="flex items-start justify-between mb-6">
                  <span className="text-sm font-medium text-blue-600 bg-blue-50 px-3 py-1 rounded-full">
                    Question {currentIndex + 1} of {questions.length}
                  </span>
                  <span className="text-sm text-gray-400">{currentQuestion.marks} mark{currentQuestion.marks > 1 ? 's' : ''}</span>
                </div>

                {/* Question text */}
                <p className="text-lg text-gray-800 font-medium mb-2 leading-relaxed">
                  {currentQuestion.question_text}
                </p>
                {currentQuestion.question_image_url && (
                  <img src={currentQuestion.question_image_url} alt="Question" className="max-w-full h-48 object-contain my-4 rounded-lg border"/>
                )}

                {/* Options */}
                <div className="space-y-3 mt-6">
                  {['A', 'B', 'C', 'D'].map(opt => {
                    const optionKey = `option_${opt.toLowerCase()}`;
                    const isSelected = answers[currentQuestion.id] === opt;
                    return (
                      <button
                        key={opt}
                        onClick={() => selectAnswer(currentQuestion.id, opt)}
                        className={`w-full text-left flex items-start gap-4 p-4 rounded-xl border-2 transition ${
                          isSelected
                            ? 'border-blue-500 bg-blue-50 text-blue-800'
                            : 'border-gray-200 hover:border-blue-300 hover:bg-blue-50/30'
                        }`}
                      >
                        <span className={`flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm ${
                          isSelected ? 'bg-blue-500 text-white' : 'bg-gray-100 text-gray-600'
                        }`}>
                          {opt}
                        </span>
                        <span className="text-base">{currentQuestion[optionKey]}</span>
                      </button>
                    );
                  })}
                </div>

                {/* Navigation buttons */}
                <div className="flex justify-between mt-8 pt-6 border-t border-gray-100">
                  <button
                    onClick={() => setCurrentIndex(i => Math.max(0, i - 1))}
                    disabled={currentIndex === 0}
                    className="flex items-center gap-2 px-5 py-2.5 rounded-xl border border-gray-200 text-gray-600 hover:bg-gray-50 disabled:opacity-40 disabled:cursor-not-allowed transition"
                  >
                    ← Previous
                  </button>

                  {answers[currentQuestion.id] && (
                    <button
                      onClick={() => {
                        const newAnswers = { ...answers };
                        delete newAnswers[currentQuestion.id];
                        setAnswers(newAnswers);
                        sessionAPI.saveAnswer(session.id, { question_id: currentQuestion.id, selected_option: null }).catch(() => {});
                      }}
                      className="text-sm text-red-500 hover:text-red-700 transition"
                    >
                      Clear Answer
                    </button>
                  )}

                  <button
                    onClick={() => setCurrentIndex(i => Math.min(questions.length - 1, i + 1))}
                    disabled={currentIndex === questions.length - 1}
                    className="flex items-center gap-2 px-5 py-2.5 rounded-xl bg-blue-600 text-white hover:bg-blue-700 disabled:opacity-40 disabled:cursor-not-allowed transition"
                  >
                    Next →
                  </button>
                </div>
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}
